package com.oracle.banking.customer.service;
import com.oracle.banking.customer.dto.CustomerDtos.*; import com.oracle.banking.customer.entity.CustomerProfile; import com.oracle.banking.customer.exception.CustomerExceptions.*; import com.oracle.banking.customer.repository.CustomerProfileRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CustomerService {private final CustomerProfileRepository profiles;public CustomerService(CustomerProfileRepository p){profiles=p;}@Transactional public Response create(Create r){if(profiles.existsByUserId(r.userId()))throw new Duplicate("Customer profile already exists");return Response.from(profiles.save(new CustomerProfile(r.userId(),r.fullName(),r.email(),r.phone())));}public Response own(String id){return Response.from(required(id));}@Transactional public Response update(String id,Update r){CustomerProfile p=required(id);p.update(r);return Response.from(p);}public Response byId(String id){return Response.from(profiles.findById(id).orElseThrow(()->new NotFound("Customer profile not found")));}private CustomerProfile required(String id){return profiles.findByUserId(id).orElseThrow(()->new NotFound("Customer profile not found"));}}
